bool StructTraits<::searchbox::mojom::UrlEmphasis::DataView, ::searchbox::mojom::UrlEmphasisPtr>::Read(
    ::searchbox::mojom::UrlEmphasis::DataView input,
    ::searchbox::mojom::UrlEmphasisPtr* output) {
  bool success = true;
  ::searchbox::mojom::UrlEmphasisPtr result(::searchbox::mojom::UrlEmphasis::New());
  
      if (success)
        result->text_is_url = input.text_is_url();
      if (success && !input.ReadDeemphasisMode(&result->deemphasis_mode))
        success = false;
      if (success && !input.ReadSchemeRange(&result->scheme_range))
        success = false;
      if (success && !input.ReadHostRange(&result->host_range))
        success = false;
      if (success)
        result->scheme_strike_through = input.scheme_strike_through();
      if (success)
        result->scheme_dangerous = input.scheme_dangerous();
  *output = std::move(result);
  return success;
}


